import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date format validation
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - department filter is optional
        String query = buildReportQuery(reportType, startDate, endDate, department);
        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end, String dept) {
        String baseQuery;
        switch (type) {
            case "sales":
                baseQuery = "SELECT order_id, customer_name, amount, order_date FROM orders";
                break;
            case "inventory":
                baseQuery = "SELECT item_id, item_name, quantity, warehouse FROM inventory";
                break;
            case "payroll":
                baseQuery = "SELECT emp_id, emp_name, salary, pay_date FROM payroll";
                break;
            default:
                baseQuery = "SELECT id, description, created_at FROM audit_log";
                break;
        }
        StringBuilder sb = new StringBuilder(baseQuery);
        sb.append(" WHERE created_at BETWEEN '").append(start).append("' AND '").append(end).append("'");
        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '").append(dept).append("'");
        }
        sb.append(" ORDER BY created_at DESC LIMIT 1000");
        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("payroll") || type.equals("audit"));
    }

    private boolean isValidDate(String date) {
        if (date == null || date.length() != 10) return false;
        return date.matches("\\d{4}-\\d{2}-\\d{2}");
    }
}
